draw_status_line:
; Draw the status line in window 2 (the 19-column panel at the right of the screen).
; Redefines and clears window 2, prints the cursor line number, then in tiny type: row 7 = Insert or Overtype (edit_flags bit 0),
; row 6 = Check: On or Off (edit_flags bit 4). Finally selects window 1 again (str_select_window1).
        ld      hl,str_define_window2
        oz      Gn_sop
        ld      hl,(cursor_line)
        inc     hl
        call    L_E80D
        ld      hl,str_status_row7
        oz      Gn_sop
        ld      a,(edit_flags)
        and     EF_OVERTYPE
        ld      hl,str_insert
        jr      z,L_D117
        ld      hl,str_overtype
L_D117:
        oz      Gn_sop
        ld      hl,str_status_row6_check
        oz      Gn_sop
        ld      hl,str_off
        ld      a,(edit_flags)
        and     EF_CHECK_ON
        jr      z,L_D12D
        ld      hl,str_on
L_D12D:
        oz      Gn_sop
        ld      hl,str_select_window1
        oz      Gn_sop
        ret


str_select_window1:
        defb    $01,$32,$48,$31,$00
str_status_row7:
; Cursor to column 0, row 7 of window 2, tiny type on. Followed by str_insert or str_overtype.
        defb    $01,$33,$40
        defb    $20,$27,$01,$32,$2b,$54,$00
str_insert:
        defb    $49
        defb    $6e,$73,$65,$72,$74,$00
str_overtype:
        defm    "Overtype"
        defb    $00
str_status_row6_check:
; Cursor to column 0, row 6 of window 2, tiny type on, then the text Check: (followed by str_off or str_on).
        defb    $01,$33,$40,$20,$26,$01,$32
        defb    $2b,$54,$43,$68,$65,$63,$6b,$3a
        defb    $00
str_off:
        defb    $4f,$66,$66,$00
str_on:
        defb    $4f,$6e,$00

str_cursor_to_prefix:
; Cursor-to prefix: SOH, 3, @. The caller sends the column and row, each plus 32.
        defb    $01,$33,$40,$00
L_D171:
; Command jump table: 47 words, indexed by dispatch code 0..46. See cmd_* handlers.
; The main loop does: HL = table + 2*code; JP (HL).
        defw    qe_main_loop
        defw    cmd_screen_up
        defw    cmd_screen_down
        defw    cmd_cursor_left
        defw    cmd_cursor_right
        defw    cmd_cursor_down
        defw    cmd_cursor_up
        defw    cmd_top_of_text
        defw    cmd_bottom_of_text
        defw    cmd_start_of_line
        defw    cmd_end_of_line
        defw    cmd_rubout
        defw    cmd_swap_case
        defw    cmd_join_lines
        defw    cmd_format_paragraph
        defw    cmd_check_this_word_or_escape
        defw    cmd_load_text
        defw    cmd_save_text
        defw    cmd_check_all_text
        defw    cmd_split_line
        defw    cmd_delete_character
        defw    cmd_delete_line
        defw    cmd_next_word
        defw    cmd_previous_word
        defw    cmd_delete_marked_block
        defw    cmd_check_as_you_type
        defw    cmd_information
        defw    cmd_check_this_word_or_escape
        defw    cmd_insert_over
        defw    cmd_check_from_cursor
        defw    cmd_insert_marker
        defw    cmd_copy_marked_block
        defw    cmd_remove_markers
        defw    cmd_move_marked_block
        defw    cmd_save_user_dictionary
        defw    cmd_load_user_dictionary
        defw    cmd_save_marked_block
        defw    cmd_search_for_string
        defw    cmd_search_and_replace
        defw    cmd_merge_text_at_cursor
        defw    cmd_check_marked_block
        defw    cmd_tab
        defw    cmd_change_name
        defw    cmd_export_text
        defw    cmd_next_match
        defw    cmd_insert_real_tab
        defw    cmd_print_out_text
cmd_print_out_text:
; Command handler: 'Print out text' - dispatch code $2E
        ld      a,$0A
        call    far_call_bank63
        jp      return_to_editor
L_D1D7:
        ld      a,(marker_flags)
        and     $01
        ret     z
        ld      bc,(cursor_line)
        ld      hl,(block_start_line)
        ld      a,b
        cp      h
        jr      c,L_D1EE
        jr      nz,L_D1F2
        ld      a,c
        cp      l
        jr      nc,L_D1F2
L_D1EE:
        dec     hl
        ld      (block_start_line),hl
L_D1F2:
        ld      a,(marker_flags)
        and     $02
        ret     z
        ld      bc,(cursor_line)
        ld      hl,(block_end_line)
        ld      a,b
        cp      h
        jr      c,L_D207
        ret     nz
        ld      a,c
        cp      l
        ret     nc
L_D207:
        dec     hl
        ld      (block_end_line),hl
        ret
L_D20C:
        ld      a,(marker_flags)
        and     $01
        ret     z
        ld      bc,(cursor_line)
        ld      hl,(block_start_line)
        ld      a,b
        cp      h
        jr      c,L_D223
        jr      nz,L_D227
        ld      a,c
        cp      l
        jr      nc,L_D227
L_D223:
        inc     hl
        ld      (block_start_line),hl
L_D227:
        ld      a,(marker_flags)
        and     $02
        ret     z
        ld      bc,(cursor_line)
        ld      hl,(block_end_line)
        ld      a,b
        cp      h
        jr      c,L_D23C
        ret     nz
        ld      a,c
        cp      l
        ret     nc
L_D23C:
        inc     hl
        ld      (block_end_line),hl
        ret
redraw_screen:
; Redraw the whole screen: the text window (far call 7 into bank 63), then the status line, then place the cursor.
        call    draw_text_window
        call    draw_status_line
place_cursor:
; Position the cursor in window 1: x = the smaller of cursor_col_limit and cursor_index, y = cursor_row.
; Both are sent as the coordinate plus SD_COORD (32), after the cursor-to prefix string.
        ld      hl,str_cursor_to_prefix
        oz      Gn_sop
        ld      a,(cursor_col_limit)
        ld      b,a
        ld      a,(cursor_index)
        cp      b
        jr      c,L_D258
        ld      a,b
L_D258:
        add     a,SD_COORD
        oz      Os_out
        ld      a,(cursor_row)
        add     a,SD_COORD
        oz      Os_out
        ret
clamp_cursor_index:
; If cursor_index is beyond line_length, sets it to line_length. Out: A = C = cursor_index. BC preserved apart from C.
        push    bc
        ld      a,(cursor_index)
        ld      c,a
        ld      a,(line_length)
        cp      c
        jr      nc,L_D273
        ld      (cursor_index),a
        ld      c,a
L_D273:
        ld      a,c
        pop     bc
        ret
translate_key_code:
; Maps raw command codes to dispatch codes: $C3 Delete line -> $15, $D3 Delete character -> $14,
; $F4 Start of line -> $09, $F5 End of line -> $0A, $F8 Previous word -> $17, $F9 Next word -> $16.
        cp      $C3
        ret     c
        jr      z,L_D291
        cp      $D3
        jr      z,L_D294
        cp      $F4
        jr      z,L_D297
        cp      $F5
        jr      z,L_D29A
        cp      $F8
        jr      z,L_D29D
        cp      $F9
        ret     nz
        ld      a,$16
        ret
L_D291:
        ld      a,$15
        ret
L_D294:
        ld      a,$14
        ret
L_D297:
        ld      a,$09
        ret
L_D29A:
        ld      a,$0A
        ret
L_D29D:
        ld      a,$17
        ret
cmd_check_from_cursor:
; Command handler: 'Check from cursor' - dispatch code $1D
        call    check_free_memory
        jp      c,L_D0D6
        ld      hl,L_D9A8
        oz      Gn_sop
        call    find_word_start
        ld      a,(line_length)
        sub     c
        ld      (scan_chars_left),a
        jp      L_D401
cmd_check_marked_block:
; Command handler: 'Check marked block' - dispatch code $28
        ld      a,(marker_flags)
        and     $02
        jp      z,qe_main_loop
        call    check_free_memory
        jp      c,L_D0D6
        call    L_E171
        ld      hl,L_D9A8
        oz      Gn_sop
        ld      hl,(cursor_line)
        ld      bc,(block_start_line)
        scf
        ccf
        sbc     hl,bc
        jr      z,L_D315
        jr      c,L_D2FB
        ld      (top_line),hl
        call    store_cursor_line
L_D2E5:
        call    step_to_prev_record
        call    dec_cursor_line
        ld      hl,(top_line)
        dec     hl
        ld      (top_line),hl
        ld      a,h
        or      l
        jr      nz,L_D2E5
        call    take_line_record
        jr      L_D315
L_D2FB:
        ld      (top_line),hl
        call    store_cursor_line
L_D301:
        call    step_to_next_record
        call    inc_cursor_line
        ld      hl,(top_line)
        inc     hl
        ld      (top_line),hl
        ld      a,h
        or      l
        jr      nz,L_D301
        call    take_line_record
L_D315:
        ld      a,(block_start_col)
        ld      (cursor_index),a
        call    find_word_start
        ld      a,(line_length)
        sub     c
        ld      (scan_chars_left),a
L_D325:
        ld      a,(line_buffer_bank)
        ld      b,a
        ld      c,$02
        oz      Os_mpb
        call    next_word_from_text
        jr      z,L_D398
        ld      (scan_ptr),hl
        ld      hl,(ptr_buffer_a)
        ld      a,(dict_target_length)
        cp      $03
        jr      c,L_D36C
        call    dictionary_lookup
        jr      nc,L_D36C
        ld      a,(edit_flags)
        and     $BF
        ld      (edit_flags),a
        call    L_D506
        call    redefine_window1
        ld      a,(edit_flags)
        and     '@'
        jr      z,L_D366
L_D359:
        ld      a,(scan_chars_left)
        ld      b,a
        ld      a,(line_length)
        sub     b
        ld      (cursor_index),a
        jr      L_D3BE
L_D366:
        ld      hl,L_D9A8
        oz      Gn_sop
L_D36C:
        ld      a,(line_buffer_bank)
        ld      b,a
        ld      c,$02
        oz      Os_mpb
        ld      bc,(block_end_line)
        ld      hl,(cursor_line)
        scf
        ccf
        sbc     hl,bc
        jr      c,L_D392
        jr      nz,L_D359
        ld      a,(block_end_col)
        ld      b,a
        ld      a,(scan_chars_left)
        ld      c,a
        ld      a,(line_length)
        sub     c
        cp      b
        jr      nc,L_D359
L_D392:
        ld      hl,(scan_ptr)
        jp      L_D325
L_D398:
        call    store_cursor_line
        jp      c,L_D0D6
        call    step_to_next_record
        jr      z,L_D3B5
        call    inc_cursor_line
        call    take_line_record
        ld      a,(line_length)
        ld      (scan_chars_left),a
        ld      hl,(line_buffer)
        jp      L_D325
L_D3B5:
        call    take_line_record
        ld      a,(line_length)
        ld      (cursor_index),a
L_D3BE:
        ld      hl,(cursor_line)
        ld      a,h
        cp      $00
        jr      nz,L_D3D2
        ld      a,(cursor_row)
        cp      l
        jr      c,L_D3D2
        jr      z,L_D3D2
        ld      a,l
        ld      (cursor_row),a
L_D3D2:
        jp      L_D467
cmd_check_all_text:
; Command handler: 'Check all text' - dispatch code $12
        call    check_free_memory
        jp      c,L_D0D6
        call    store_cursor_line
L_D3DE:
        call    step_to_prev_record
        jr      nz,L_D3DE
        ld      hl,$0000
        ld      (cursor_line),hl
        ld      hl,L_D9A8
        oz      Gn_sop
L_D3EF:
        call    take_line_record
        call    check_free_memory
        jp      c,L_D0D6
        ld      a,(line_length)
        ld      (scan_chars_left),a
        ld      hl,(line_buffer)
L_D401:
        ld      a,(line_buffer_bank)
        ld      b,a
        ld      c,$02
        oz      Os_mpb
        call    next_word_from_text
        jr      z,L_D44E
        ld      (scan_ptr),hl
        ld      hl,(ptr_buffer_a)
        ld      a,(dict_target_length)
        cp      $03
        jr      c,L_D449
        call    dictionary_lookup
        jr      nc,L_D449
        ld      a,(edit_flags)
        and     $BF
        ld      (edit_flags),a
        call    L_D506
        call    redefine_window1
        ld      a,(edit_flags)
        and     '@'
        jr      z,L_D443
        ld      a,(scan_chars_left)
        ld      b,a
        ld      a,(line_length)
        sub     b
        ld      (cursor_index),a
        jp      L_D467
L_D443:
        ld      hl,L_D9A8
        oz      Gn_sop
L_D449:
        ld      hl,(scan_ptr)
        jr      L_D401
L_D44E:
        call    store_cursor_line
        jp      c,L_D0D6
L_D454:
        call    step_to_next_record
        jr      z,L_D45E
        call    inc_cursor_line
        jr      L_D3EF
L_D45E:
        call    take_line_record
        ld      a,(line_length)
