L_D467:
; End of the check: the ignored words are only for this check. Swap the lists, free every ignored word and the table, swap back.
        ld      a,(edit_flags)
        and     $F1
        or      $02
        ld      (edit_flags),a
        call    swap_word_lists
        call    word_list_clear
        ld      hl,(user_dict_ptr)
        ld      a,h
        or      l
        jr      z,L_D490
        ld      a,(user_dict_bank)
        ld      bc,$004E
        ld      ix,(pool_main)
        oz      Os_mfr
        ld      hl,$0000
        ld      (user_dict_ptr),hl
L_D490:
        call    swap_word_lists
        jp      L_C5AF
L_D496:
        ld      a,(line_buffer_bank)
        ld      b,a
        ld      c,$02
        oz      Os_mpb
        ld      a,$0C
        oz      Os_out
        ld      a,(scan_chars_left)
        ld      b,a
        ld      a,(line_length)
        sub     b
        ld      (char_scratch),a
        ld      hl,(line_buffer)
        ld      a,(cursor_col_limit)
        ld      c,a
        ld      a,(char_scratch)
        sub     c
        ld      e,a
        jr      nc,L_D4BD
        ld      e,$00
L_D4BD:
        ld      d,$00
        add     hl,de
        ld      a,(cursor_col_limit)
        ld      c,a
        ld      a,(line_length)
        cp      c
        jr      nc,L_D4CB
        ld      c,a
L_D4CB:
        ld      a,(line_buffer)
        ld      d,a
        ld      a,(word_start_ptr)
        sub     d
        sub     e
        ld      d,a
        ld      a,(dict_target_length)
        add     a,d
        ld      e,a
        ld      a,d
        cp      $00
        jr      nz,L_D4E2
        call    toggle_reverse
L_D4E2:
        ld      a,e
        cp      $00
        jr      nz,L_D4EA
        call    toggle_reverse
L_D4EA:
        ld      a,(hl)
        oz      Os_out
        inc     hl
        dec     c
        jr      z,L_D4FF
        dec     d
        jr      nz,L_D4F7
        call    toggle_reverse
L_D4F7:
        dec     e
        jr      nz,L_D4EA
        call    toggle_reverse
        jr      L_D4EA
L_D4FF:
        ld      hl,L_D983
        oz      Gn_sop
