        oz      Gn_nln
        ld      hl,L_DA55
        call    open_dialog_default
        ld      hl,L_D9B2
        oz      Gn_sop
        jp      L_D60C
L_D542:
        call    redefine_window1
        ld      hl,L_D9A4
        oz      Gn_sop
        ld      a,' '
        oz      Os_out
        oz      Os_out
        call    L_D496
        oz      Gn_nln
L_D557:
        ld      hl,L_DA55
        call    open_dialog_default
        ld      hl,L_D9B2
        oz      Gn_sop
        ld      a,(edit_flags)
        and     $BF
        ld      (edit_flags),a
        ld      a,$00
        ld      (wf_menu_sel),a
        ld      c,'#'
        call    L_DABC
L_D575:
        oz      Os_in
        call    c,L_DADE
        jr      c,L_D575
        cp      $00
        jr      nz,L_D5CA
        oz      Os_in
        call    c,L_DADE
        jr      c,L_D575
        cp      $1B
        jr      nz,L_D597
        ld      a,(edit_flags)
        or      '@'
        ld      (edit_flags),a
        call    redefine_window1
