open_dialog_with_title:
; Open a dialog box with a title bar in window 3.
; IN: HL = the title text, BC = the window description (the outer x,y,w,d, a NUL, then the inner x,y,w,d).
; Draws the outer window (type $83), prints the title centred, makes the title line reverse across 75 characters,
; then redefines window 3 as the inner window (type $81) below the title and selects it.
        push    hl
        push    bc
        ld      hl,str_define_window3_prefix
        oz      Gn_sop
        pop     hl
        oz      Gn_sop
        inc     hl
        push    hl
        ld      hl,str_dialog_type_83
        oz      Gn_sop
        pop     bc
        pop     hl
        push    bc
        oz      Gn_sop
        ld      hl,str_dialog_title_bar
        oz      Gn_sop
        pop     hl
        oz      Gn_sop
        ld      hl,str_dialog_type_81
